NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'I John'

CHAPTERS = {
    1: {
        1: 'Was da von Anfang war, was wir gehört und mit unseren Augen gesehen, was wir beschaut und mit unseren Händen betastet haben vom Worte des Lebens -',
        2: 'Und das Leben erschien, und wir haben es gesehen und bezeugen und verkündigen euch das Leben, das ewig ist, das beim Vater war und uns erschienen ist.',
        3: 'Was wir gesehen und gehört haben, verkündigen wir euch, auf daß auch ihr mit uns Gemeinschaft habet; und unsere Gemeinschaft ist mit dem Vater und mit Seinem Sohn Jesus Christus.',
        4: 'Und solches schreiben wir euch, auf daß eure Freude vollkommen sei.',
        5: 'Und das ist die Verkündigung, die wir von Ihm gehört haben und euch verkündigen, daß Gott ein Licht und in Ihm keine Finsternis ist.',
        6: 'Wenn wir sagen, daß wir Gemeinschaft mit Ihm haben, und wandeln in der Finsternis, so lügen wir und tun die Wahrheit nicht.',
        7: 'So wir aber im Licht wandeln, wie Er im Licht ist, so haben wir Gemeinschaft miteinander, und das Blut Seines Sohnes Jesus Christus reinigt uns von aller Sünde.',
        8: 'So wir sagen, wir haben keine Sünde, so täuschen wir uns selbst, und die Wahrheit ist nicht in uns.',
        9: 'So wir aber unsere Sünden bekennen, so ist Er treu und gerecht, daß Er uns die Sünden vergibt und uns reinigt von aller Ungerechtigkeit.',
        10: 'So wir sagen, wir hätten nicht gesündigt, so machen wir Ihn zum Lügner, und Sein Wort ist nicht in uns.',
    },
    2: {
        1: 'Meine Kindlein, solches schreibe ich euch, auf daß ihr nicht sündigt; und so einer gesündigt hat, haben wir einen Beistand beim Vater, Jesus Christus, den Gerechten.',
        2: 'Und Er ist die Versöhnung für unsere Sünden, nicht allein aber für die unseren, sondern auch für die der ganzen Welt.',
        3: 'Und daran erkennen wir, daß wir Ihn erkannt haben, so wir Seine Gebote halten.',
        4: 'Wer da sagt: Ich kenne Ihn, und hält Seine Gebote nicht, der ist ein Lügner und in solchem ist die Wahrheit nicht.',
        5: 'Wer aber Sein Wort hält, in dem ist in Wahrheit die Liebe vollkommen geworden. Daran erkennen wir, daß wir in Ihm sind.',
        6: 'Wer da sagt, er bleibe in Ihm, der muß auch wandeln, gleich wie Er gewandelt hat.',
        7: 'Brüder, ich schreibe euch kein neu Gebot, sondern ein alt Gebot, das ihr von Anfang an hattet; und das alte Gebot ist das Wort, das ihr von Anfang an gehört habt.',
        8: 'Wiederum schreibe ich euch ein neu Gebot, das wahr ist in Ihm und in euch; denn die Finsternis geht vorbei und das wahre Licht scheint bereits.',
        9: 'Wer da sagt, er sei im Licht, und haßt seinen Bruder, der ist noch in der Finsternis.',
        10: 'Wer seinen Bruder liebt, der bleibt im Licht, und kein Ärgernis ist in ihm.',
        11: 'Wer aber seinen Bruder haßt, der ist in der Finsternis und wandelt in der Finsternis, und weiß nicht, wohin er geht, weil die Finsternis seine Augen verblendet hat.',
        12: 'Ich schreibe euch, Kindlein, weil die Sünden euch um Seines Namens willen vergeben sind.',
        13: 'Ich schreibe euch, Väter, weil ihr Den, Der von Anfang ist, erkannt habt. Ich schreibe euch, Jüngere, weil ihr den Bösen überwunden habt. Ich schreibe euch, Kindlein, weil ihr den Vater erkannt habt.',
        14: 'Ich habe euch, Väter, geschrieben, weil ihr Den, Der von Anfang ist, erkannt habt. Ich habe euch, Jüngere, geschrieben, weil ihr stark seid und das Wort Gottes in euch bleibt und ihr den Bösen überwunden habt.',
        15: 'Habt nicht lieb die Welt, noch was in der Welt ist. So jemand die Welt lieb hat, in dem ist die Liebe des Vaters nicht.',
        16: 'Denn alles, was in der Welt ist, des Fleisches Lust und der Augen Lust und die Hoffart des Lebens, ist nicht vom Vater, sondern von der Welt.',
        17: 'Und die Welt vergeht mit ihrer Lust; wer aber den Willen Gottes tut, der bleibt in Ewigkeit.',
        18: 'Kindlein, es ist die letzte Stunde; und wie ihr gehört habt, daß der Widerchrist kommt, so sind auch jetzt schon viele Widerchristen gekommen. Daran erkennen wir, daß es um die letzte Stunde ist.',
        19: 'Von uns sind sie ausgegangen, sie waren aber nicht von uns; denn wenn sie von uns gewesen wären, so wären sie bei uns geblieben; aber es sollte offenbar werden, daß sie nicht alle von uns sind.',
        20: 'Und ihr habt die Weihe vom Heiligen und wißt alles.',
        21: 'Ich habe nicht an euch geschrieben, als ob ihr die Wahrheit nicht wüßtet, sondern weil ihr sie wißt, und daß keine Lüge aus der Wahrheit kommt.',
        22: 'Denn wer ist der Lügner, wo nicht der, so da leugnet, daß Jesus der Christ ist? Der ist der Widerchrist, der den Vater und den Sohn verleugnet.',
        23: 'Jeder, der den Sohn verleugnet, hat auch den Vater nicht.',
        24: 'Was ihr denn von Anfang gehört habt, das bleibe in euch. Wenn in euch bleibt, was ihr von Anfang an gehört habt, so werdet ihr auch in dem Sohne und in dem Vater bleiben.',
        25: 'Und das ist die Verheißung, die Er uns verheißen hat, das ewige Leben.',
        26: 'Solches habe ich euch geschrieben wegen derer, die euch verführen wollen.',
        27: 'Und die Salbung, die ihr von Ihm empfangen habt, bleibt in euch, und ihr bedürft nicht, daß euch jemand lehre, sondern wie eben die Salbung euch belehrt über alles, so ist sie auch wahr und ist keine Lüge, und wie sie euch gelehrt hat, so bleibt dabei.',
        28: 'Und nun, Kindlein, bleibt in Ihm, auf daß wir, wenn Er erscheinen wird, freudige Zuversicht haben, und bei Seiner Zukunft vor Ihm nicht zuschanden werden.',
        29: 'So ihr nun wißt, daß Er gerecht ist, erkennt auch, daß jeder, der die Gerechtigkeit übt, aus Ihm geboren ist.',
    },
    3: {
        1: 'Seht, welche Liebe uns der Vater erzeigt hat, daß wir sollten Gottes Kinder heißen. Darum erkennt uns die Welt nicht, weil sie Ihn nicht erkannt hat.',
        2: 'Geliebte, wir sind nun Gottes Kinder, und noch ist nicht offenbar, was wir sein werden. Wir wissen aber, daß wir, wenn Er erscheinen wird, Ihm gleich sein werden; denn wir werden Ihn sehen, wie Er ist.',
        3: 'Und ein jeglicher, der solche Hoffnung auf Ihn hat, reinigt sich, gleich wie Er rein ist.',
        4: 'Jeder, der Sünde tut, übertritt das Gesetz, und die Sünde ist Übertretung des Gesetzes.',
        5: 'Und ihr wißt, daß Er erschienen ist, auf daß Er unsere Sünden wegnehme, und in Ihm keine Sünde ist.',
        6: 'Jeder, der in Ihm bleibt, sündigt nicht. Jeder, der sündigt, hat Ihn nicht gesehen, noch Ihn erkannt.',
        7: 'Kindlein, laßt euch von niemand irre führen. Wer tut, was recht ist, ist gerecht, gleich wie Er gerecht ist.',
        8: 'Wer Sünde tut, ist vom Teufel; denn der Teufel sündigt von Anfang. Dazu ist der Sohn Gottes erschienen, daß Er die Werke des Teufels zerstöre.',
        9: 'Jeder, der aus Gott geboren ist, tut keine Sünde, weil Sein Same in ihm bleibt, und er kann nicht sündigen, weil er aus Gott geboren ist.',
        10: 'Daran sind offenbar die Kinder Gottes und die Kinder des Teufels. Jeder, der nicht recht tut und seinen Bruder nicht liebt, ist nicht aus Gott.',
        11: 'Denn das ist die Botschaft, die ihr von Anfang gehört habt, daß wir einander lieben sollen.',
        12: 'Nicht wie Kain, der aus dem Argen war und seinen Bruder mordete. Und warum hat er ihn gemordet? Weil seine Werke böse waren, die seines Bruders aber gerecht.',
        13: 'Verwundert euch nicht, meine Brüder, daß euch die Welt haßt.',
        14: 'Wir wissen, daß wir aus dem Tod ins Leben übergegangen sind; denn wir lieben die Brüder. Wer den Bruder nicht liebt, der bleibt im Tode.',
        15: 'Jeder, der seinen Bruder haßt, ist ein Mörder, und ihr wißt, daß in keinem Mörder das ewige Leben bleiben kann.',
        16: 'Daran haben wir die Liebe erkannt, daß Er Sein Leben für uns gelassen. Auch wir sollen für die Brüder das Leben lassen.',
        17: 'Wenn aber einer dieser Welt Güter hat und sieht seinen Bruder Not leiden, und verschließt sein Herz vor ihm, wie bleibt da die Liebe Gottes in ihm?',
        18: 'Meine Kindlein, laßt uns nicht lieben mit Worten, noch mit der Zunge, sondern mit der Tat und mit der Wahrheit.',
        19: 'Und dadurch erkennen wir, daß wir aus der Wahrheit sind und können unsere Herzen vor Ihm beruhigen,',
        20: 'Daß, wenn uns unser Herz verdammt, Gott größer ist, denn unser Herz und alle Dinge erkennt.',
        21: 'Geliebte, wenn uns unser Herz nicht verdammt, dann haben wir ein freudiges Vertrauen zu Gott.',
        22: 'Und alles, was wir von Ihm erbitten, erlangen wir von Ihm, weil wir Seine Gebote halten, und tun, was vor Ihm wohlgefällig ist.',
        23: 'Und das ist Sein Gebot, daß wir an den Namen Seines Sohnes Jesus Christus glauben und einander lieben, wie Er uns geboten hat.',
        24: 'Wer Seine Gebote hält, der bleibt in Ihm und Er in ihm. Und daran erkennen wir, daß Er in uns bleibt, an dem Geiste, den Er uns gegeben hat.',
    },
    4: {
        1: 'Geliebte, glaubt nicht jeglichem Geiste, sondern prüft die Geister, ob sie von Gott sind; denn viele falsche Propheten sind in die Welt ausgegangen.',
        2: 'Daran erkennt den Geist Gottes: Jeder Geist, der da bekennt, daß Jesus Christus ist in das Fleisch gekommen, ist von Gott;',
        3: 'Und ein jeglicher Geist, der Jesus Christus nicht als ins Fleisch gekommen bekennt, der ist nicht von Gott, und das ist der',
        4: 'Ihr seid aus Gott, Kindlein, und habt sie überwunden, denn Der in euch ist, ist größer, als der in der Welt ist.',
        5: 'Sie sind von der Welt, darum reden sie von der Welt und die Welt hört auf sie.',
        6: 'Wir sind von Gott; wer Gott erkennt, der hört auf uns; wer nicht aus Gott ist, hört nicht auf uns. Daran erkennen wir den Geist der Wahrheit und den Geist der Irrlehre.',
        7: 'Geliebte, laßt uns einander lieben; denn die Liebe ist aus Gott und der da liebt, ist aus Gott geboren und erkennt Gott.',
        8: 'Wer nicht liebt, hat Gott nicht erkannt; denn Gott ist die Liebe.',
        9: 'Darin hat sich die Liebe Gottes an uns geoffenbart, daß Gott Seinen eingeborenen Sohn in die Welt gesendet hat, daß wir durch Ihn leben sollten.',
        10: 'Darin besteht die Liebe, nicht daß wir Gott liebten, sondern daß Er uns liebte und Seinen Sohn zur Versöhnung für unsere Sünden gesandt hat.',
        11: 'Geliebte, wenn uns nun Gott also geliebt hat, so sollen auch wir einander lieben.',
        12: 'Niemand hat Gott jemals geschaut. So wir einander lieben, so bleibt Gott in uns und Seine Liebe ist völlig in uns.',
        13: 'Daran erkennen wir, daß wir in Ihm bleiben, und Er in uns, daß Er uns von Seinem Geist gegeben hat.',
        14: 'Und wir haben geschaut und zeugen, daß der Vater den Sohn als Heiland der Welt gesendet hat.',
        15: 'Wer nun bekennt, daß Jesus der Sohn Gottes ist, in dem bleibt Gott, und er in Gott.',
        16: 'Und wir haben die Liebe, so Gott zu uns hat, erkannt, und an sie geglaubt. Gott ist Liebe, und wer in der Liebe bleibt, bleibt in Gott und Gott in ihm.',
        17: 'Daran ist die Liebe völlig in uns, auf daß wir freudiges Vertrauen haben am Tage des Gerichts, weil, wie Er ist, so auch wir in dieser Welt sind.',
        18: 'Furcht ist nicht in der Liebe, sondern völlige Liebe treibt die Furcht aus; denn Furcht hat Strafe, und wer sich fürchtet, ist nicht vollkommen in der Liebe.',
        19: 'Laßt uns Ihn lieben, denn Er hat uns zuerst geliebt.',
        20: 'So jemand spricht: Ich liebe Gott, und haßt seinen Bruder, der ist ein Lügner; denn wer seinen Bruder nicht liebt, den er sieht, wie kann er Gott lieben, Den er nicht sieht?',
        21: 'Und dies Gebot haben wir von Ihm, daß, wer Gott liebt, auch seinen Bruder liebe.',
    },
    5: {
        1: 'Wer da glaubt, daß Jesus ist der Christ, Der ist aus Gott geboren; und wer da liebt Den, der Ihn gezeugt hat, der liebt auch Den, Der aus Ihm geboren ist.',
        2: 'Daran erkennen wir, daß wir Gottes Kinder lieben, wenn wir Gott lieben und Seine Gebote halten.',
        3: 'Denn das ist die Liebe zu Gott, daß wir Seine Gebote halten; und Seine Gebote sind nicht schwer.',
        4: 'Denn alles, was aus Gott geboren ist, überwindet die Welt, und unser Glaube ist der Sieg, der die Welt überwunden hat.',
        5: 'Wer anders überwindet die Welt, wo nicht der, so da glaubt, daß Jesus der Sohn Gottes ist?',
        6: 'Dieser ist es, Der da gekommen ist mit Wasser und Blut, Jesus Christus, nicht mit Wasser allein, sondern mit Wasser und Blut, und der Geist ist es, der da zeugt, weil der Geist die Wahrheit ist.',
        7: 'Denn drei sind, die da zeugen im Himmel: der Vater, das Wort und der Heilige Geist, und diese drei sind eins.',
        8: 'Und drei sind, die da zeugen auf Erden: der Geist und das Wasser und das Blut, und diese drei sind eins.',
        9: 'So wir der Menschen Zeugnis annehmen, so ist Gottes Zeugnis noch größer; denn das ist Gottes Zeugnis, das Er von Seinem Sohne gezeugt hat.',
        10: 'Wer da glaubt an den Sohn Gottes, der hat das Zeugnis in ihm selber; wer nicht an Gott glaubt, der hat Ihn zum Lügner gemacht, weil er nicht geglaubt hat an das Zeugnis, das Gott von Seinem Sohn gezeugt hat.',
        11: 'Und das ist das Zeugnis, daß Gott uns das ewige Leben gegeben hat, und solches Leben ist in Seinem Sohn.',
        12: 'Wer den Sohn hat, der hat das Leben; wer den Sohn Gottes nicht hat, der hat das Leben nicht.',
        13: 'Solches habe ich euch geschrieben, die ihr an den Namen des Sohnes Gottes glaubt, auf daß ihr wißt, daß ihr ewiges Leben habt, und auf daß ihr glaubt an den Namen des Sohnes Gottes.',
        14: 'Und das ist die freudige Zuversicht, die wir zu Ihm haben, daß, so wir etwas bitten nach Seinem Willen, Er uns erhört.',
        15: 'Und so wir wissen, daß Er uns erhört in dem, um was wir Ihn auch bitten mögen, so wissen wir, daß wir das von Ihm Erbetene erlangen.',
        16: 'Wenn einer seinen Bruder eine Sünde begehen sieht, nicht zum Tode, so mag er bitten und Er wird ihm Leben schenken, denen, die da sündigen nicht zum Tode. Es gibt aber eine Sünde zum Tode, dafür sage ich nicht, daß er bitten soll.',
        17: 'Alles Unrecht ist Sünde, aber es gibt eine Sünde, die nicht zum Tode ist.',
        18: 'Wir wissen, daß, wer von Gott geboren ist, nicht sündigt, daß vielmehr der von Gott Geborene sich bewahrt und der Arge ihn nicht antastet.',
        19: 'Wir wissen, daß wir aus Gott sind und die ganze Welt im Argen liegt.',
        20: 'Wir wissen aber, daß der Sohn Gottes gekommen ist und uns Einsicht gegeben hat, daß wir den Wahrhaftigen erkennen, und so sind wir in dem Wahrhaftigen, in Seinem Sohne Jesus Christus. Dieser ist der wahrhaftige Gott und das ewige Leben.',
        21: 'Kindlein, hütet euch vor den Abgöttern! Amen.',
    },
}
